// TerraTwin research suite: data-driven only. No synthetic NASA values or similarity scores.
let terraReport = { analogDiscovery: null, simulation: null };
const terraStatus = (id, text, error=false) => { const el=document.getElementById(id); if(el){el.textContent=text;el.classList.toggle("error-message",error);} };
function parseCSV(text){
 const rows=[];let row=[],cell="",quoted=false;
 for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&text[i+1]==='"'&&quoted){cell+='"';i++;}else if(c==='"'){quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell="";}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell="";}else cell+=c;}
 row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(rows.length<2)throw new Error("CSV needs a header row and at least one data row.");const headers=rows.shift().map(x=>x.trim());return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,(r[i]||"").trim()])));
}
async function readResearchDataset(file){const text=await file.text();let rows;if(file.name.toLowerCase().endsWith(".csv"))rows=parseCSV(text);else{const parsed=JSON.parse(text);rows=Array.isArray(parsed)?parsed:(parsed.records||parsed.features?.map(f=>({...f.properties,geometry:f.geometry}))||parsed.data);}
 if(!Array.isArray(rows)||!rows.length||!rows.every(x=>x&&typeof x==="object"))throw new Error("Expected a JSON array or an object with a records/data array.");return rows;
}
function runAnalogAnalysis(rows,targetName,targetWorld){
 const norm=s=>String(s||"").trim().toLowerCase();const nameKey=["name","site","location","region"].find(k=>Object.keys(rows[0]).some(h=>norm(h)===k));const worldKey=["world","body","planet"].find(k=>Object.keys(rows[0]).some(h=>norm(h)===k));
 if(!nameKey||!worldKey)throw new Error("Dataset schema required: each row needs name (or site/location) and world (or body/planet) columns.");
 const get=(r,k)=>r[Object.keys(r).find(h=>norm(h)===k)];const target=rows.find(r=>norm(get(r,nameKey))===norm(targetName)&&norm(get(r,worldKey))===norm(targetWorld));if(!target)throw new Error(`Target row not found: ${targetName} (${targetWorld}). Include a row for the target site.`);
 const candidates=rows.filter(r=>norm(get(r,worldKey))==="earth");if(!candidates.length)throw new Error("No Earth candidate rows found. Set world=Earth for Earth analog sites.");
 const keys=Object.keys(target).filter(k=>{const nk=norm(k);if([norm(nameKey),norm(worldKey),"latitude","longitude","lat","lon","id","url","source","units"].includes(nk))return false;return Number.isFinite(Number(target[k]))&&candidates.some(c=>Number.isFinite(Number(c[k])));});if(!keys.length)throw new Error("No shared numeric measurement columns found. Add numeric features with matching column names and units.");
 const pool=[target,...candidates];const ranges=Object.fromEntries(keys.map(k=>{const vals=pool.map(r=>Number(r[k])).filter(Number.isFinite);return [k,{min:Math.min(...vals),max:Math.max(...vals)}]}));
 const ranked=candidates.map(c=>{let sum=0,n=0;for(const k of keys){const range=ranges[k],span=range.max-range.min||1,a=(Number(target[k])-range.min)/span,b=(Number(c[k])-range.min)/span;sum+=(a-b)**2;n++;}const distance=Math.sqrt(sum/n);return {name:get(c,nameKey),score:Math.max(0,Math.min(100,(1-distance)*100)),distance};}).sort((a,b)=>a.distance-b.distance);
 return {target:targetName,world:targetWorld,features:keys,candidates:ranked,method:"Equal-weight normalized Euclidean distance across shared numeric fields. This is exploratory and not scientifically validated until feature selection, units, uncertainty and weighting are reviewed."};
}
document.getElementById("runAnalog")?.addEventListener("click",async()=>{
 const target=document.getElementById("analogTarget").value.trim(),world=document.getElementById("analogWorld").value,box=document.getElementById("analogResults");
 box.innerHTML="";
 if(!target){terraStatus("analogStatus",language==="ar"?"اكتب اسم المنطقة أو الموقع أولًا.":"Enter a target region or site first.",true);return;}
 const btn=document.getElementById("runAnalog");btn.disabled=true;
 terraStatus("analogStatus",language==="ar"?"جاري البحث في أرشيف NASA وجمع بيانات المصادر…":"Searching NASA archives and collecting source metadata…");
 try{
  const r=await fetch(`/api/terratwin/collect?world=${encodeURIComponent(world)}&target=${encodeURIComponent(target)}`,{signal:AbortSignal.timeout(55000)});
  const d=await r.json();if(!r.ok)throw new Error(d.error||"NASA archive discovery failed.");
  terraReport.analogDiscovery=d;
  const card=(x)=>`<div class="analog-row"><b>${escapeHTML(x.name||"NASA record")}</b><small>${escapeHTML(x.source||"NASA")} · ${escapeHTML(x.target||"Target not specified")} · ${escapeHTML(x.mission||"Mission not specified")} · ${escapeHTML(x.instrument||"Instrument not specified")}</small><p>${escapeHTML((x.description||"No description supplied by archive.").slice(0,420))}</p><a href="${escapeHTML(x.url||"#")}" target="_blank" rel="noopener noreferrer">Open original NASA record ↗</a>${x.kind==="collection"?`<button type="button" class="outline-btn harmony-check-btn" data-harmony-id="${escapeHTML(x.id||"")}">Check Harmony support</button>`:""}<div class="harmony-capability-output" aria-live="polite"></div></div>`;
  box.innerHTML=`<h4>${language==="ar"?"البيانات التي عُثر عليها":"Discovered archive records"}</h4><p>${language==="ar"?"سجلات الكواكب":"Planetary records"}: ${d.planetary.length} · ${language==="ar"?"مجموعات بيانات الأرض":"Earth collections"}: ${d.earth.length}</p><h4>Planetary archive — ${escapeHTML(world)}</h4>${d.planetary.length?d.planetary.map(card).join(""):"<p>No matching planetary records returned.</p>"}<h4>Earth observation collections (analogs)</h4>${d.earth.length?d.earth.map(card).join(""):"<p>No matching Earth collections returned.</p>"}<div class="terra-note">${escapeHTML(d.analysis.message)}</div>${d.errors?.length?`<p>${d.errors.map(e=>escapeHTML(e.source+": "+e.message)).join("<br>")}</p>`:""}`;
  terraStatus("analogStatus",language==="ar"?`اكتمل البحث. تم العثور على ${d.planetary.length+d.earth.length} سجلًا/مجموعة من مصادر NASA. تم حفظ بيانات البحث مؤقتًا لتقليل الطلبات المتكررة.`:`Discovery complete: ${d.planetary.length+d.earth.length} NASA records/collections found. Search metadata is cached to reduce repeat requests.`);
 }catch(e){terraStatus("analogStatus",e.message,true);}finally{btn.disabled=false;}
});


// Collection-specific NASA Harmony capability check and bounded subset request builder.
document.getElementById("analogResults")?.addEventListener("click",async e=>{
 const btn=e.target.closest("[data-harmony-id]");if(!btn)return;
 const id=btn.dataset.harmonyId,output=btn.parentElement.querySelector(".harmony-capability-output");
 const status=document.getElementById("harmonySubsetStatus"),collection=document.getElementById("harmonyCollectionId"),submit=document.getElementById("buildSubsetRequest");
 btn.disabled=true;btn.textContent="Checking NASA Harmony…";output.textContent="Checking collection-specific capabilities…";
 try{
  const response=await fetch(`/api/terratwin/capabilities?collectionId=${encodeURIComponent(id)}`,{signal:AbortSignal.timeout(25000)}),data=await response.json();
  if(!response.ok)throw new Error(data.error||"Harmony capability lookup failed.");
  const c=data.capabilities,variables=(data.variables||[]).map(v=>v.name||v.id||v.label).filter(Boolean);
  output.innerHTML=`<p><b>Harmony capabilities</b>: spatial ${c.bboxSubset?"supported":"not advertised"} · temporal ${c.temporalSubset?"supported":"not advertised"} · variable ${c.variableSubset?"supported":"not advertised"}</p><small>${escapeHTML(variables.slice(0,12).join(", ")||"No variable list supplied by Harmony")}</small>`;
  if(c.bboxSubset&&c.temporalSubset){collection.value=id;submit.disabled=false;document.getElementById("subsetVariable").value=variables[0]||"all";status.textContent="Collection selected. Set your bounding box and dates, then build a NASA Harmony subset request. Earthdata Login may be required.";}
  else{status.textContent="This collection does not advertise both spatial and temporal subsetting. Use its original archive link; no unsupported subset request was generated.";}
 }catch(error){output.textContent=error.message;status.textContent=error.message;}
 finally{btn.disabled=false;btn.textContent="Check Harmony support";}
});

document.getElementById("harmonySubsetForm")?.addEventListener("submit",async e=>{
 e.preventDefault();const status=document.getElementById("harmonySubsetStatus"),out=document.getElementById("harmonySubsetLink");
 const params=new URLSearchParams({collectionId:document.getElementById("harmonyCollectionId").value,variable:document.getElementById("subsetVariable").value.trim()||"all",west:document.getElementById("subsetWest").value,south:document.getElementById("subsetSouth").value,east:document.getElementById("subsetEast").value,north:document.getElementById("subsetNorth").value,start:document.getElementById("subsetStart").value,end:document.getElementById("subsetEnd").value});
 status.textContent="Validating subset request with NASA Harmony…";out.innerHTML="";
 try{const response=await fetch(`/api/terratwin/subset-url?${params}`,{signal:AbortSignal.timeout(25000)}),data=await response.json();if(!response.ok)throw new Error(data.error||"Could not create subset request.");
  out.innerHTML=`<div class="analog-row"><b>NASA subset request is ready</b><p>${escapeHTML(data.note)}</p><a href="${escapeHTML(data.url)}" target="_blank" rel="noopener noreferrer">Open NASA Harmony request ↗</a><small>Collection ${escapeHTML(data.collectionId)} · ${escapeHTML(data.time.start)} to ${escapeHTML(data.time.end)} · max 10 granules per request</small></div>`;
  status.textContent="Request built. NASA may ask you to sign in with Earthdata Login and may process the job asynchronously.";
 }catch(error){status.textContent=error.message;}
});

document.getElementById("missionSimForm")?.addEventListener("submit",e=>{e.preventDefault();const days=Number(document.getElementById("simDays").value),available=Number(document.getElementById("simPower").value),demand=Number(document.getElementById("simNeed").value),slopeRaw=document.getElementById("simSlope").value,slope=slopeRaw===""?null:Number(slopeRaw);if(!(days>0&&available>=0&&demand>=0)){terraStatus("simResults",language==="ar"?"راجع القيم المدخلة.":"Check the entered values.",true);return;}const margin=available-demand,total=available*days,need=demand*days;const result={days,available,demand,margin,total,need,slope,screening:margin<0?"Power deficit":margin===0?"No power reserve":"Positive power reserve"};terraReport.simulation=result;const slopeText=slope===null?(language==="ar"?"لم يتم إدخال الميل":"Not supplied"):slope>25?(language==="ar"?"ميل مرتفع — يحتاج مراجعة للمسار":"High slope — route review needed"):slope>15?(language==="ar"?"ميل متوسط — يتطلب تحققًا":"Moderate slope — verify route constraints"):(language==="ar"?"الميل ضمن نطاق الفحص الأولي":"Within preliminary screening range");document.getElementById("simResults").innerHTML=`<h4>${language==="ar"?"نتيجة فحص تخطيطي":"Planning screen result"}</h4><div class="sim-metrics"><div><small>${language==="ar"?"هامش الطاقة اليومي":"Daily energy margin"}</small><b>${margin.toFixed(2)} kWh/day</b></div><div><small>${language==="ar"?"إجمالي الطاقة المتاحة":"Total available energy"}</small><b>${total.toFixed(2)} kWh</b></div><div><small>${language==="ar"?"إجمالي الطلب":"Total demand"}</small><b>${need.toFixed(2)} kWh</b></div></div><p><b>${escapeHTML(result.screening)}</b> · ${escapeHTML(slopeText)}</p><small>${language==="ar"?"فحص أولي مبني فقط على مدخلاتك؛ لا يتضمن التخزين أو الفقد أو دورات الليل أو متطلبات السلامة.":"Input-only preliminary check; excludes storage, losses, night cycles and safety requirements."}</small>`;});


// Interactive scientific map workspace. Earth layers are streamed from NASA GIBS;
// Mars/Moon use bundled global surface imagery until a calibrated archive product is selected.
(function initScientificMap(){
 const host=document.getElementById("scienceMap");if(!host)return;
 const worldSelect=document.getElementById("scienceMapWorld"),layerSelect=document.getElementById("scienceMapLayer"),baseToggle=document.getElementById("mapBaseToggle"),dataToggle=document.getElementById("mapDataToggle"),status=document.getElementById("mapStatus");
 const setStatus=t=>{if(status)status.textContent=t;};
 const loadLeaflet=()=>new Promise((resolve,reject)=>{if(window.L)return resolve();const css=document.querySelector('link[href*="leaflet.css"]');if(!css){const l=document.createElement("link");l.rel="stylesheet";l.href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";document.head.appendChild(l);}const script=document.createElement("script");script.src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";script.onload=resolve;script.onerror=()=>reject(new Error("Map library could not load. Check your internet connection."));document.head.appendChild(script);});
 loadLeaflet().then(()=>{
  const L=window.L;host.innerHTML="";let map=null,base=null,overlay=null,planetaryImage=null;
  const gibs=(id,format="jpg")=>L.tileLayer(`https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/${id}/default/{time}/GoogleMapsCompatible_Level9/{z}/{y}/{x}.${format}`,{time:new Date(Date.now()-86400000).toISOString().slice(0,10),tileSize:256,maxZoom:9,attribution:'NASA GIBS / EOSDIS',crossOrigin:true});
  const layers={base:()=>gibs("MODIS_Terra_CorrectedReflectance_TrueColor"),thermal:()=>gibs("MODIS_Terra_Land_Surface_Temp_Day","png"),vegetation:()=>gibs("MODIS_Terra_NDVI_8Day","png"),fires:()=>gibs("VIIRS_SNPP_Thermal_Anomalies_375m_All","png")};
  function refresh(){const world=worldSelect.value,layer=layerSelect.value;if(map)map.remove();base=overlay=planetaryImage=null;host.innerHTML="";
   const isEarth=world==="Earth";layerSelect.disabled=!isEarth;dataToggle.disabled=!isEarth;map=L.map(host,{crs:isEarth?L.CRS.EPSG3857:L.CRS.Simple,worldCopyJump:isEarth,zoomControl:true,preferCanvas:true,minZoom:isEarth?1:-3,maxZoom:isEarth?9:3});
   if(isEarth){map.setView([20,0],2);base=layers.base();if(baseToggle.checked)base.addTo(map);if(dataToggle.checked&&layer!=="base"){overlay=layers[layer]();overlay.setOpacity(.72);overlay.addTo(map);}setStatus("Live NASA GIBS Earth imagery. Overlay: "+({base:"Natural-color satellite imagery",thermal:"MODIS land-surface temperature",vegetation:"MODIS NDVI vegetation index",fires:"VIIRS thermal anomalies"}[layer])+". Dates and coverage follow NASA product availability.");}
   else{const url=world==="Mars"?"/assets/planet-textures/2k_mars.jpg":"/assets/moon-realistic-map.png",bounds=[[0,0],[1024,2048]];map.setView([512,1024],-1);planetaryImage=L.imageOverlay(url,bounds,{opacity:baseToggle.checked?1:0});planetaryImage.addTo(map);map.setMaxBounds(bounds);setStatus((world==="Mars"?"Mars global surface imagery":"Lunar global surface imagery")+" is displayed as an interactive reference basemap. Calibrated MOLA / LOLA elevation overlays are not currently loaded; unsupported scientific overlays are not fabricated.");}
   setTimeout(()=>map.invalidateSize(),120);
  }
  worldSelect.addEventListener("change",refresh);layerSelect.addEventListener("change",refresh);baseToggle.addEventListener("change",refresh);dataToggle.addEventListener("change",refresh);refresh();
  if("ResizeObserver" in window)new ResizeObserver(()=>map&&map.invalidateSize()).observe(host);
 }).catch(e=>{host.innerHTML=`<div class="map-loading">${escapeHTML(e.message)}</div>`;setStatus("NASA map services require an internet connection.");});
})();
